class OwnershipCleanupSystem:
    def process(self, manager):
        for _id, entity in manager.get_entities('population').items():
            # Only process planets, not ships
            if entity.type == 'ship':
                continue

            # Check if the entity has an ownership component and population is zero or None
            population = getattr(entity, 'population', None)
            if population is None or population == 0:
                # Remove ownership if population is zero or None
                if hasattr(entity, 'owner_id'):
                    delattr(entity, 'owner_id')

                # Remove explicit population field if it's 0 to clean up data
                if population == 0 and hasattr(entity, 'population'):
                    delattr(entity, 'population')
